const raw = $input.first().json;
const b = raw.body || raw;
const now = new Date();
const source = String(b.source || 'chatgpt');
const title = String(b.title || 'Untitled Capture');
const content = String(b.content || b.text || b.note || '');
const typeHint = b.type_hint ? String(b.type_hint) : '';
const sourceUrl = b.url || b.source_url || b.link || '';
const created = now.toISOString();
const date = created.slice(0, 10);
const compactStamp = created.replace(/[-:]/g, '').replace(/\..+$/, '').replace('T', '-');
const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 70) || 'untitled-capture';
let inboxPrefix;
try { inboxPrefix = (process.env.MIND_INBOX_PATH || 'capture/inbox').replace(/^\/+|\/+$/g, '') || 'capture/inbox'; } catch(e) { inboxPrefix = 'capture/inbox'; }
const filepath = inboxPrefix + '/' + compactStamp + '-' + slug + '.md';

return [{
  json: {
    source,
    title,
    content,
    typeHint,
    sourceUrl,
    created,
    date,
    filepath,
    queuedForClassification: true,
    classifier: 'Mind Steward',
  },
}];

function utf8ToBase64(str) {
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    let code = str.charCodeAt(i);
    if (code < 0x80) { bytes.push(code); }
    else if (code < 0x800) { bytes.push(0xc0 | (code >> 6)); bytes.push(0x80 | (code & 0x3f)); }
    else if (code >= 0xd800 && code <= 0xdbff) {
      i++;
      const next = str.charCodeAt(i);
      const fullCode = 0x10000 + (((code & 0x3ff) << 10) | (next & 0x3ff));
      bytes.push(0xf0 | (fullCode >> 18));
      bytes.push(0x80 | ((fullCode >> 12) & 0x3f));
      bytes.push(0x80 | ((fullCode >> 6) & 0x3f));
      bytes.push(0x80 | (fullCode & 0x3f));
    } else {
      bytes.push(0xe0 | (code >> 12));
      bytes.push(0x80 | ((code >> 6) & 0x3f));
      bytes.push(0x80 | (code & 0x3f));
    }
  }
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let output = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i], b = bytes[i + 1], c = bytes[i + 2];
    output += chars[a >> 2];
    output += chars[((a & 3) << 4) | ((b ?? 0) >> 4)];
    output += b === undefined ? '=' : chars[((b & 15) << 2) | ((c ?? 0) >> 6)];
    output += c === undefined ? '=' : chars[c & 63];
  }
  return output;
}

function yamlString(value) {
  return JSON.stringify(String(value ?? ''));
}

const capture = $('Prepare Capture').first().json;
const sourceLines = [];
if (capture.sourceUrl) sourceLines.push('- URL: ' + capture.sourceUrl);
if (capture.typeHint) sourceLines.push('- Type hint: ' + capture.typeHint);
const sourceBlock = sourceLines.length ? sourceLines.join('\n') : '- Source: ' + capture.source;

const md = [
  '---',
  'type: capture',
  'source: ' + yamlString(capture.source),
  'status: queued',
  'para_type: inbox',
  'confidence: 0',
  'signal_quality: 0',
  'title: ' + yamlString(capture.title),
  'created: ' + yamlString(capture.created),
  'mind_steward_status: queued',
  'mind_steward_local_only: true',
  'mind_steward_task_type: mind_capture_classification',
  '---',
  '',
  '# ' + capture.title,
  '',
  '## Source',
  sourceBlock,
  '',
  '## Content',
  capture.content,
  '',
].join('\n');

return [{
  json: {
    ...capture,
    markdown: md,
    base64: utf8ToBase64(md),
  },
}];

const processed = $('Build Inbox Note').first().json;
const current = $json;

let sha = undefined;

if (current && current.sha && typeof current.sha === "string") {
  sha = current.sha;
}

return [{
  json: {
    ...processed,
    sha,
    fileExists: Boolean(sha),
  }
}];
